  let state = { user: null, restaurants: [], settings: { id: 1, particles_enabled: true, sound_enabled: false }, group: "all", query: "", wheelMode: "all", editingId: null, pendingDeleteId: null, formScores: {}, selectedImage: null, selectedImageUrl: "", spinning: false, wheelRotation: 0, deferredInstall: null };
  PEOPLE.forEach(p => state.formScores[p] = null);

