      { id: crypto.randomUUID(), name: "北市场酸菜火锅", category: "火锅", address: "和平区", visited: true, visited_date: new Date(Date.now() - 86400000 * 10).toISOString().slice(0, 10), discounts: [], notes: "酸菜白肉，冬天很稳。", wby_score: 9, sol_score: 8, wl_score: 8, wcy_score: null, created_at: now }
