    $$(".wheel-mode").forEach(b => b.addEventListener("click", () => { state.wheelMode = b.dataset.mode; $$(".wheel-mode").forEach(x => x.classList.toggle("active", x === b)); renderWheel(); })); $("#wheel-category").addEventListener("change", renderWheel); $("#min-score").addEventListener("input", () => { $("#min-score-value").textContent = $("#min-score").value; renderWheel(); }); $("#spin-button").addEventListener("click", spinWheel);
    $("#particles-toggle").addEventListener("change", savePreference); $("#sound-toggle").addEventListener("change", savePreference); $("#export-button").addEventListener("click", exportData); $("#logout-button").addEventListener("click", logout); $("#cancel-delete").addEventListener("click", () => closeModal("confirm-modal")); $("#confirm-delete").addEventListener("click", confirmDelete); $("#detail-modal").addEventListener("click", e => { if (e.target === e.currentTarget) closeModal("detail-modal"); }); $("#result-modal").addEventListener("click", e => { if (e.target === e.currentTarget) closeModal("result-modal"); });
