  function switchView(name) { $$(".view-section").forEach(s => s.classList.add("hidden")); $("#view-" + name).classList.remove("hidden"); $$(".tab-button").forEach(b => b.classList.toggle("active", b.dataset.view === name)); if (name === "add" && !state.editingId) resetForm(); if (name === "wheel") renderWheel(); if (name === "settings") renderSettings(); window.scrollTo({ top: 0, behavior: "smooth" }); }
