  function renderIdentity() { $("#current-person").textContent = LABELS[state.user] || "WBY"; $("#header-avatar").src = state.settings[`${state.user || "wby"}_avatar`] || "icon.svg"; }
  function renderTaxonomies() { const cats = [...new Set(state.restaurants.map(r => r.category).filter(Boolean))].sort(); $("#category-options").innerHTML = cats.map(c => `<option value="${esc(c)}">`).join(""); const current = $("#wheel-category").value; $("#wheel-category").innerHTML = `<option value="">全部类别</option>${cats.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join("")}`; $("#wheel-category").value = cats.includes(current) ? current : ""; }
  function filteredLibrary() { return state.restaurants.filter(r => { const g = state.group === "all" || (state.group === "visited" ? r.visited : !r.visited); const hay = `${r.name} ${r.category || ""} ${r.address || ""} ${r.notes || ""}`.toLowerCase(); return g && (!state.query || hay.includes(state.query)); }); }
  function renderLibrary() { const list = filteredLibrary(); $("#count-all").textContent = state.restaurants.length; $("#count-visited").textContent = state.restaurants.filter(r => r.visited).length; $("#count-wishlist").textContent = state.restaurants.filter(r => !r.visited).length; $$(".seg-button").forEach(b => b.classList.toggle("active", b.dataset.group === state.group)); $("#restaurant-list").innerHTML = list.map(cardMarkup).join(""); $("#empty-library").classList.toggle("hidden", list.length > 0); $$(".restaurant-card").forEach(c => c.addEventListener("click", e => { if (!e.target.closest("button")) openDetail(c.dataset.id); })); $$('[data-action="edit"]').forEach(b => b.addEventListener("click", () => editRestaurant(b.dataset.id))); $$('[data-action="delete"]').forEach(b => b.addEventListener("click", () => askDelete(b.dataset.id))); }
  function avatar(p) { return state.settings[`${p}_avatar`] || "icon.svg"; }
  function scorePills(r) { return PEOPLE.map(p => `<span class="score-pill"><img src="${esc(avatar(p))}" alt="">${LABELS[p]} ${scoreText(r[`${p}_score`])}</span>`).join(""); }
  function cardMarkup(r) { const a = average(r), image = r.image_url ? `<img class="restaurant-image" src="${esc(r.image_url)}" alt="${esc(r.name)}" loading="lazy">` : `<div class="restaurant-image placeholder-image">🍽️</div>`; return `<article class="restaurant-card warm-card" data-id="${esc(r.id)}"><div class="relative">${image}<span class="status-badge">${r.visited ? "✅ 已吃过" : "🤤 想吃"}</span></div><div class="p-4"><div class="flex justify-between gap-3"><div class="min-w-0"><h3 class="text-xl font-black truncate">${esc(r.name)}</h3><p class="text-sm muted truncate">${r.category ? esc(r.category) : "未分类"}${r.address ? " · " + esc(r.address) : ""}</p></div><div class="text-right shrink-0"><p class="text-2xl font-black accent-text">${a === null ? "—" : a.toFixed(1)}</p><p class="text-[10px] muted">当前平均分</p></div></div><div class="flex flex-wrap gap-1.5 mt-4">${scorePills(r)}</div><div class="flex items-center justify-between mt-4"><span class="rating-chip">${rating(a)}</span><div class="flex gap-1"><button class="btn btn-soft icon-btn" data-action="edit" data-id="${esc(r.id)}" aria-label="编辑">✏️</button><button class="btn btn-danger icon-btn" data-action="delete" data-id="${esc(r.id)}" aria-label="删除">🗑️</button></div></div></div></article>`; }
  function openDetail(id) { const r = state.restaurants.find(x => String(x.id) === String(id)); if (!r) return; const a = average(r); $("#detail-panel").innerHTML = `${r.image_url ? `<img src="${esc(r.image_url)}" class="w-full h-56 object-cover rounded-2xl mb-5" alt="${esc(r.name)}">` : `<div class="h-40 rounded-2xl bg-peach grid place-items-center text-6xl mb-5">🍽️</div>`}<div class="flex justify-between gap-4"><div><span class="status-badge inline-block static">${r.visited ? "✅ 已吃过" : "🤤 想吃"}</span><h3 class="text-2xl font-black mt-2">${esc(r.name)}</h3><p class="muted text-sm">${r.address ? "📍 " + esc(r.address) : "沈阳地址待补充"}</p></div><div class="text-center"><p class="text-3xl accent-text font-black">${a === null ? "—" : a.toFixed(1)}</p><p class="text-xs muted">${rating(a)}</p></div></div><div class="grid grid-cols-2 gap-3 my-5">${PEOPLE.map(p => `<div class="score-box"><img class="avatar mx-auto" src="${esc(avatar(p))}" alt=""><p class="font-black mt-2">${LABELS[p]} · ${scoreText(r[`${p}_score`])}</p></div>`).join("")}</div><div class="flex flex-wrap gap-2 mb-4"><span class="chip">${esc(r.category || "未分类")}</span>${(r.discounts || []).map(d => `<span class="chip">${esc(d)}</span>`).join("")}${r.visited_date ? `<span class="chip">📅 ${esc(r.visited_date)}</span>` : ""}</div><div class="note whitespace-pre-wrap">${esc(r.notes || "还没有备注。")}</div><div class="grid grid-cols-3 gap-2 mt-5"><button class="btn btn-soft" id="detail-close">关闭</button><button class="btn btn-soft" id="detail-edit">编辑</button><button class="btn btn-danger" id="detail-delete">删除</button></div>`; $("#detail-modal").classList.remove("hidden"); $("#detail-close").onclick = () => closeModal("detail-modal"); $("#detail-edit").onclick = () => { closeModal("detail-modal"); editRestaurant(r.id); }; $("#detail-delete").onclick = () => { closeModal("detail-modal"); askDelete(r.id); }; }
  function closeModal(id) { $("#" + id).classList.add("hidden"); }
  function buildScorePickers() { $("#score-pickers").innerHTML = PEOPLE.map(p => `<div><label class="label">${LABELS[p]} <span id="${p}-score-label">未评分</span></label><div id="${p}-score" class="score-grid">${Array.from({ length: 11 }, (_, i) => `<button type="button" class="score-button" data-person="${p}" data-score="${i}">${i}</button>`).join("")}</div></div>`).join(""); $$(".score-button").forEach(b => b.addEventListener("click", () => { state.formScores[b.dataset.person] = Number(b.dataset.score); renderScorePicker(b.dataset.person); })); }
  function renderScorePicker(p) { const v = state.formScores[p]; $$(`#${p}-score .score-button`).forEach(b => b.classList.toggle("selected", Number(b.dataset.score) === v)); $(`#${p}-score-label`).textContent = v === null ? "未评分" : `${v} / 10`; }
  function addDiscount(v) { const input = $("#discounts"), vals = input.value.split(/[,，]/).map(x => x.trim()).filter(Boolean); if (!vals.includes(v)) vals.push(v); input.value = vals.join(", "); }
  async function previewImage(e) { const f = e.target.files[0]; if (!f) return; try { state.selectedImage = await compressImage(f); state.selectedImageUrl = URL.createObjectURL(state.selectedImage); $("#image-preview").src = state.selectedImageUrl; $("#image-preview").classList.remove("hidden"); $("#image-placeholder").classList.add("hidden"); } catch (_) { toast("图片读取失败", true); } }
  async function compressImage(file, max = 1600, quality = .82) { const bitmap = await createImageBitmap(file); const scale = Math.min(1, max / Math.max(bitmap.width, bitmap.height)); const c = document.createElement("canvas"); c.width = Math.round(bitmap.width * scale); c.height = Math.round(bitmap.height * scale); c.getContext("2d").drawImage(bitmap, 0, 0, c.width, c.height); return new Promise(resolve => c.toBlob(resolve, "image/jpeg", quality)); }
  async function uploadImage(blob, folder) { if (!blob) return null; if (!cloudMode) return blobToDataUrl(blob); const path = `${folder}/${Date.now()}-${crypto.randomUUID()}.jpg`; const { error } = await client.storage.from("meal-images").upload(path, blob, { contentType: "image/jpeg" }); if (error) throw error; return client.storage.from("meal-images").getPublicUrl(path).data.publicUrl; }
  const blobToDataUrl = blob => new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(r.result); r.onerror = reject; r.readAsDataURL(blob); });
  function resetForm() { state.editingId = null; state.selectedImage = null; state.selectedImageUrl = ""; PEOPLE.forEach(p => state.formScores[p] = null); $("#restaurant-form").reset(); $("#restaurant-id").value = ""; $("#form-title").textContent = "添加餐厅"; $("#submit-restaurant").textContent = "保存餐厅"; $("#cancel-edit").classList.add("hidden"); $("#image-preview").classList.add("hidden"); $("#image-placeholder").classList.remove("hidden"); PEOPLE.forEach(renderScorePicker); }
  function editRestaurant(id) { const r = state.restaurants.find(x => String(x.id) === String(id)); if (!r) return; state.editingId = r.id; switchView("add"); $("#restaurant-id").value = r.id; $("#form-title").textContent = "编辑餐厅"; $("#submit-restaurant").textContent = "保存修改"; $("#cancel-edit").classList.remove("hidden"); $("#restaurant-name").value = r.name || ""; $("#restaurant-category").value = r.category || ""; $("#restaurant-address").value = r.address || ""; $("#visited-date").value = r.visited_date || ""; $("#is-visited").checked = !!r.visited; $("#discounts").value = (r.discounts || []).join(", "); $("#notes").value = r.notes || ""; PEOPLE.forEach(p => { state.formScores[p] = r[`${p}_score`] === null || r[`${p}_score`] === undefined ? null : Number(r[`${p}_score`]); renderScorePicker(p); }); if (r.image_url) { $("#image-preview").src = r.image_url; $("#image-preview").classList.remove("hidden"); $("#image-placeholder").classList.add("hidden"); } }
  async function saveRestaurant(e) { e.preventDefault(); const name = $("#restaurant-name").value.trim(); if (!name) return; const payload = { name, category: $("#restaurant-category").value.trim() || "其他", address: $("#restaurant-address").value.trim() || "", visited: $("#is-visited").checked, visited_date: $("#visited-date").value || null, discounts: $("#discounts").value.split(/[,，]/).map(x => x.trim()).filter(Boolean), notes: $("#notes").value.trim() || "", created_by: state.user, ...Object.fromEntries(PEOPLE.map(p => [`${p}_score`, state.formScores[p]])) }; const btn = $("#submit-restaurant"); btn.disabled = true; btn.textContent = "正在保存…"; try { if (state.selectedImage) payload.image_url = await uploadImage(state.selectedImage, state.editingId || "restaurants"); if (!cloudMode) { if (state.editingId) Object.assign(state.restaurants.find(r => r.id === state.editingId), payload); else state.restaurants.unshift({ id: crypto.randomUUID(), created_at: new Date().toISOString(), ...payload }); saveDemo(); } else { const q = state.editingId ? client.from("meal_restaurants").update(payload).eq("id", state.editingId) : client.from("meal_restaurants").insert(payload); const { error } = await q; if (error) throw error; await refreshRestaurants(); } toast(ADD_LINES[Math.floor(Math.random() * ADD_LINES.length)]); resetForm(); switchView("library"); } catch (err) { toast(`保存失败：${err.message || "请稍后再试"}`, true); } finally { btn.disabled = false; btn.textContent = state.editingId ? "保存修改" : "保存餐厅"; } }
  function askDelete(id) { state.pendingDeleteId = id; $("#confirm-modal").classList.remove("hidden"); }
  async function confirmDelete() { const id = state.pendingDeleteId; if (!id) return; if (!cloudMode) { state.restaurants = state.restaurants.filter(r => r.id !== id); saveDemo(); } else { const { error } = await client.from("meal_restaurants").delete().eq("id", id); if (error) { toast("删除失败", true); return; } await refreshRestaurants(); } state.pendingDeleteId = null; closeModal("confirm-modal"); toast("已删除，家庭会议少一项议题"); }
  function eligible() { const cat = $("#wheel-category").value, min = Number($("#min-score").value); return state.restaurants.filter(r => (state.wheelMode === "all" || (state.wheelMode === "visited" ? r.visited : !r.visited)) && (!cat || r.category === cat) && (average(r) === null ? min === 0 : average(r) >= min)); }
  function renderWheel() { const list = eligible(); $("#eligible-count").textContent = list.length; drawWheel(list); }
  function drawWheel(list) { const c = $("#wheel-canvas"), ctx = c.getContext("2d"), n = Math.max(list.length, 1), cx = c.width / 2, cy = c.height / 2, rad = 300; ctx.clearRect(0, 0, c.width, c.height); if (!list.length) { ctx.fillStyle = "#FFE6CC"; ctx.beginPath(); ctx.arc(cx, cy, rad, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = "#8A5A44"; ctx.font = "bold 24px system-ui"; ctx.textAlign = "center"; ctx.fillText("先加几家餐厅", cx, cy); return; } const colors = ["#F2C078", "#E7A977", "#DFA58A", "#F5D6A6", "#C98B6B", "#E8C39E"]; list.forEach((r, i) => { const a0 = i * Math.PI * 2 / n + state.wheelRotation, a1 = (i + 1) * Math.PI * 2 / n + state.wheelRotation; ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, rad, a0, a1); ctx.closePath(); ctx.fillStyle = colors[i % colors.length]; ctx.fill(); ctx.strokeStyle = "#FFF8E8"; ctx.lineWidth = 5; ctx.stroke(); ctx.save(); ctx.translate(cx, cy); ctx.rotate((a0 + a1) / 2); ctx.fillStyle = "#53352A"; ctx.font = "bold 20px system-ui"; ctx.textAlign = "right"; ctx.fillText(r.name.slice(0, 12), rad - 18, 6); ctx.restore(); }); ctx.beginPath(); ctx.arc(cx, cy, 58, 0, Math.PI * 2); ctx.fillStyle = "#FFF8E8"; ctx.fill(); ctx.strokeStyle = "#D48166"; ctx.lineWidth = 8; ctx.stroke(); }
  async function spinWheel() { if (state.spinning) return; const list = eligible(); if (!list.length) { toast("没有符合条件的餐厅，换个筛选条件试试！", true); return; } state.spinning = true; $("#spin-button").disabled = true; $("#ready-copy").textContent = "SPINNING…"; const winner = list[Math.floor(Math.random() * list.length)], index = list.indexOf(winner), n = list.length, target = -(index + .5) * Math.PI * 2 / n, start = state.wheelRotation, turns = Math.PI * 2 * (5 + Math.random() * 2), end = start + turns + (target - start) % (Math.PI * 2), duration = 4200, t0 = performance.now(); await new Promise(resolve => { const frame = now => { const p = Math.min(1, (now - t0) / duration), eased = 1 - Math.pow(1 - p, 3); state.wheelRotation = start + (end - start) * eased; drawWheel(list); if (p < 1) requestAnimationFrame(frame); else resolve(); }; requestAnimationFrame(frame); }); state.spinning = false; $("#spin-button").disabled = false; $("#ready-copy").textContent = "READY GO"; showResult(winner); }
  function showResult(r) { const a = average(r); $("#result-panel").innerHTML = `<div class="result-burst">✦ ✧ ✦</div><p class="eyebrow">THE WHEEL HAS SPOKEN</p><h3 class="text-3xl font-black mt-2">就吃你了！</h3>${r.image_url ? `<img src="${esc(r.image_url)}" class="w-full h-44 object-cover rounded-2xl mt-5" alt="">` : `<div class="h-36 rounded-2xl bg-peach grid place-items-center text-6xl mt-5">🍽️</div>`}<h4 class="text-2xl font-black mt-4">${esc(r.name)}</h4><p class="accent-text font-black text-xl mt-1">${a === null ? "—" : a.toFixed(1)} / 10 · ${rating(a)}</p><div class="flex flex-wrap justify-center gap-1.5 mt-3">${scorePills(r)}</div><p class="muted text-sm mt-4 whitespace-pre-wrap">${esc(r.notes || "备注：先到先得，谁饿谁先点菜。")}</p><div class="grid grid-cols-2 gap-3 mt-6"><button class="btn btn-soft" id="spin-again">再转一次</button><button class="btn btn-primary" id="result-detail">查看详情</button></div>`; $("#result-modal").classList.remove("hidden"); $("#spin-again").onclick = () => { closeModal("result-modal"); spinWheel(); }; $("#result-detail").onclick = () => { closeModal("result-modal"); openDetail(r.id); }; if (state.settings.particles_enabled) confetti(); toast(FUN_LINES[Math.floor(Math.random() * FUN_LINES.length)]); }
  function confetti() { const colors = ["#D48166", "#F2C078", "#8DB6A5", "#E58C68"]; for (let i = 0; i < 18; i++) { const el = document.createElement("span"); el.className = "confetti"; el.style.left = `${40 + Math.random() * 20}%`; el.style.background = colors[i % colors.length]; el.style.setProperty("--x", `${(Math.random() - .5) * 260}px`); el.style.setProperty("--r", `${Math.random() * 720 - 360}deg`); document.body.appendChild(el); setTimeout(() => el.remove(), 1800); } }
  async function savePreference() { const payload = { particles_enabled: $("#particles-toggle").checked, sound_enabled: $("#sound-toggle").checked }; if (!cloudMode) { Object.assign(state.settings, payload); saveDemo(); } else await client.from("meal_settings").update(payload).eq("id", 1); }
  function renderSettings() { $("#stat-total").textContent = state.restaurants.length; $("#stat-visited").textContent = state.restaurants.filter(r => r.visited).length; $("#stat-wishlist").textContent = state.restaurants.filter(r => !r.visited).length; $("#particles-toggle").checked = state.settings.particles_enabled !== false; $("#sound-toggle").checked = !!state.settings.sound_enabled; $("#avatar-settings").innerHTML = PEOPLE.map(p => `<label class="text-center cursor-pointer"><img src="${esc(avatar(p))}" class="avatar-lg mx-auto" alt="${LABELS[p]}"><span class="chip mt-2 inline-block">${LABELS[p]} 更换头像</span><input data-avatar="${p}" type="file" accept="image/*" class="hidden"></label>`).join(""); $$('[data-avatar]').forEach(input => input.addEventListener("change", e => updateAvatar(e.target.dataset.avatar, e.target.files[0]))); const buckets = [{ label: "很美味", min: 8, max: 10 }, { label: "还不错", min: 6, max: 8 }, { label: "一般", min: 4, max: 6 }, { label: "别吃了", min: 0, max: 4 }]; $("#score-distribution").innerHTML = buckets.map(b => { const n = state.restaurants.filter(r => { const a = average(r); return a !== null && a >= b.min && (b.max === 10 ? a <= b.max : a < b.max); }).length; return `<div class="flex items-center gap-3"><span class="w-20 text-sm font-black">${b.label}</span><div class="bar"><span style="width:${state.restaurants.length ? Math.min(100, n / state.restaurants.length * 100) : 0}%"></span></div><b class="text-sm">${n}</b></div>`; }).join(""); }
  async function updateAvatar(p, file) { if (!file) return; try { const blob = await compressImage(file, 700, .86), url = await uploadImage(blob, `avatars/${p}`); if (!cloudMode) { state.settings[`${p}_avatar`] = url; saveDemo(); } else { const { error } = await client.from("meal_settings").update({ [`${p}_avatar`]: url }).eq("id", 1); if (error) throw error; await loadSettings(); } renderAll(); toast(`${LABELS[p]} 的头像更新好了`); } catch (e) { toast("头像上传失败", true); } }
